package com.ptms.service; import com.ptms.domain.*; import com.ptms.dto.*; import com.ptms.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class DashboardService{private final EmployeeRepository e;private final VisitorRepository v;private final ParkingTicketRepository t;private final TicketIssueRepository i;public DashboardService(EmployeeRepository e,VisitorRepository v,ParkingTicketRepository t,TicketIssueRepository i){this.e=e;this.v=v;this.t=t;this.i=i;}public DashboardResponse summary(){Map<Integer,Long>m=new LinkedHashMap<>();for(int h:List.of(1,2,4,6,8,12))m.put(h,t.countByStatusAndDurationHours(TicketStatus.AVAILABLE,h));return new DashboardResponse(e.count(),v.count(),t.countByStatus(TicketStatus.AVAILABLE),t.countByStatus(TicketStatus.ISSUED),i.findByStatusOrderByCreatedAtAsc(IssueStatus.PENDING).size(),m);}}
